"""Vietnamese member pages served by the Canvas host."""
PAGE = '''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IBEE · Thành viên</title><meta name="theme-color" content="#16B9F4"><link rel="icon" href="/brand/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/brand/icon-180.png"><link rel="manifest" href="/manifest.webmanifest">
<script>try{var theme=JSON.parse(localStorage.getItem('infinite-canvas:theme_store')||'{}');document.documentElement.classList.toggle('light',theme.state?.theme!=='dark');}catch(e){}</script><style>:root{--bg:#0b1b32;--surface:#102442;--input:#193758;--border:#294862;--text:#edfaff;--muted:#aecbd9;--link:#16b9f4}html.light{--bg:#f7fcff;--surface:#fff;--input:#eaf8ff;--border:#c8e8f7;--text:#102442;--muted:#47627a;--link:#087fb8}body{margin:0;background:var(--bg);color:var(--text);font:16px system-ui}*{box-sizing:border-box}header{padding:18px 5%;border-bottom:1px solid var(--border);display:flex;gap:20px;flex-wrap:wrap;align-items:center}a{color:var(--link);text-decoration:none}main{max-width:1000px;margin:40px auto;padding:0 20px}form,.card{padding:24px;border:1px solid var(--border);border-radius:16px;background:var(--surface);margin:18px 0}label{display:block;margin:14px 0 6px}input,textarea,select{width:100%;padding:12px;border:1px solid var(--border);border-radius:8px;color:inherit;background:var(--input);font:inherit}textarea{min-height:160px}button{cursor:pointer;background:#087fb8;color:white;border:0;padding:11px 18px;border-radius:8px;font:inherit;margin:8px 8px 0 0}button:disabled{opacity:.5;cursor:wait}.secondary{background:#294862}.danger{background:#9c3547}#notice{white-space:pre-wrap;color:#ffcb8e;min-height:24px}p{line-height:1.6}.muted{color:var(--muted)}.auth{max-width:480px;margin:auto}.row{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.content{white-space:pre-wrap;overflow-wrap:anywhere}.hidden{display:none}small{color:var(--muted)}h1{font-size:28px}h2{font-size:20px}.account-heading{margin-bottom:24px}.account-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.summary-card{border:1px solid var(--border);border-radius:12px;padding:18px;background:var(--surface);min-width:0}.summary-card strong{display:block;margin-top:8px;overflow-wrap:anywhere}.account-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:24px;align-items:start}.account-directory{margin-top:32px;border-top:1px solid var(--border);padding-top:24px}.account-list{margin:16px 0}.account-row{display:flex;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid var(--border)}.account-row>div{flex:1;min-width:0;overflow-wrap:anywhere}.account-row p{margin:4px 0}.status-badge{font-size:12px;padding:5px 9px;border-radius:20px;background:var(--input);white-space:nowrap}.status-approved{color:#22c55e}.status-pending{color:#e8a947}.status-blocked{color:#f16a7d}.member-actions{margin-bottom:24px}form{min-width:0}input[readonly]{opacity:.7;cursor:default}header a{padding:4px 0}header .ibee-brand{display:inline-flex;align-items:center;gap:8px;color:var(--text);font-size:20px;font-weight:800;letter-spacing:.08em}header .ibee-brand img{width:30px;height:30px}html.light button.secondary{background:#ddf5ff;color:#102442}header a[aria-current=page]{color:var(--text);border-bottom:2px solid #16b9f4}.profile-form textarea{min-height:100px}@media(max-width:700px){.account-grid{grid-template-columns:1fr;gap:0}main{margin:24px auto;padding:0 14px}header{padding:12px 14px;gap:14px;font-size:14px}.card,form{padding:18px}.account-row{gap:8px;flex-wrap:wrap}.account-row>div{flex-basis:calc(100% - 120px)}.account-row button{margin-top:0;padding:8px 12px}.row{align-items:stretch}.row>*{flex-basis:100%}.account-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.summary-card{padding:12px}.summary-card strong{font-size:14px}}</style></head><body><header><a class="ibee-brand" href="/"><img src="/brand/bee-symbol.svg" alt="" width="30" height="30">IBEE</a><a href="/image">Tạo ảnh</a><a href="/video">Tạo video</a><a href="/prompts">Thư viện lời nhắc</a><a href="/account">Quản lý tài khoản</a><a id="adminLink" class="hidden" href="/members">Quản lý thành viên</a><span id="account"></span><button id="logout" class="secondary hidden">Đăng xuất</button></header><main><div id="notice" role="status" aria-live="polite"></div><div id="app"></div></main>
<script>
let me=null, prompts=[], editing=null;const app=document.getElementById('app'),notice=document.getElementById('notice');
function message(text){notice.textContent=text;}
async function api(path,data){const options={credentials:'same-origin',headers:{}};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''};options.body=JSON.stringify(data);}const r=await fetch('/member-api/'+path,options);const out=await r.json();if(!r.ok)throw Error(out.error||'Yêu cầu thất bại.');return out;}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function action(parent,text,fn,cls){const b=node('button',text,cls);b.type='button';b.onclick=async()=>{b.disabled=true;message('');try{await fn();}catch(e){message(e.message);}finally{b.disabled=false;}};parent.append(b);return b;}
function field(form,label,name,type='text'){const id='field-'+name;const lab=node('label',label);lab.htmlFor=id;form.append(lab);const input=document.createElement(type==='textarea'?'textarea':'input');input.id=id;input.name=name;if(type!=='textarea')input.type=type;input.required=true;if(type==='password'){input.minLength=8;input.maxLength=128;input.autocomplete=location.pathname==='/register'?'new-password':'current-password';}if(name==='phone'){input.autocomplete='tel';input.inputMode='tel';input.placeholder='09xxxxxxxx';}form.append(input);return input;}
function authPage(register){app.className='auth';app.append(node('h1',register?'Đăng ký thành viên':'Đăng nhập'));app.append(node('p',register?'Tài khoản mới cần được admin duyệt trước khi sử dụng.':'Dùng số điện thoại và mật khẩu của bạn.','muted'));const form=document.createElement('form');field(form,'Số điện thoại','phone','tel');field(form,'Mật khẩu','password','password');if(register)field(form,'Nhập lại mật khẩu','password_confirm','password');const submit=node('button',register?'Đăng ký':'Đăng nhập');submit.type='submit';form.append(submit);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;message('');try{const data=Object.fromEntries(new FormData(form));const out=await api(register?'register':'login',data);if(register){form.reset();message(out.message);}else location.href='/';}catch(err){message(err.message);}finally{submit.disabled=false;}};app.append(form);const a=node('a',register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký');a.href=register?'/login':'/register';app.append(a);}
async function membersPage(){app.replaceChildren(node('h1','Quản lý thành viên'));const data=await api('members');app.append(node('p','Thành viên mới phải được duyệt để đăng nhập. Khóa tài khoản sẽ kết thúc phiên đăng nhập hiện có.','muted'));const labels={pending:'Chờ duyệt',approved:'Đã duyệt',blocked:'Đã khóa'};for(const u of data.members){const card=node('section',undefined,'card');card.append(node('h2',u.phone),node('p',(u.role==='admin'?'Admin · ':'Thành viên · ')+labels[u.status]));if(u.role!=='admin'){for(const [status,label] of [['approved','Duyệt / Mở khóa'],['blocked','Khóa / Từ chối']]){if(status!==u.status)action(card,label,async()=>{await api('members',{id:u.id,status});await membersPage();},status==='blocked'?'danger':'');}}app.append(card);}}
function editor(){const wrap=document.getElementById('editor');wrap.replaceChildren();const form=document.createElement('form');form.append(node('h2',editing?'Sửa lời nhắc':'Thêm lời nhắc'));const title=field(form,'Tiêu đề','title'),content=field(form,'Nội dung lời nhắc','content','textarea');title.maxLength=200;content.maxLength=50000;const select=document.createElement('select');select.name='scope';select.id='prompt-scope';const label=node('label','Phạm vi hiển thị');label.htmlFor=select.id;form.append(label);for(const [val,text] of me.role==='admin'?[['shared','Thư viện chung — mọi thành viên đều thấy'],['private','Riêng tư — chỉ chủ sở hữu và admin']]:[['private','Thư viện riêng của tôi']]){const option=node('option',text);option.value=val;select.append(option);}form.append(select);if(editing){title.value=editing.title;content.value=editing.content;select.value=editing.scope;}const save=node('button','Lưu lời nhắc');save.type='submit';form.append(save);action(form,'Hủy / Tạo mới',()=>{editing=null;editor();},'secondary');form.onsubmit=async e=>{e.preventDefault();save.disabled=true;message('');try{await api('prompts',{id:editing?.id,title:title.value,content:content.value,scope:select.value});editing=null;await libraryPage();message('Đã lưu lời nhắc.');}catch(err){message(err.message);}finally{save.disabled=false;}};wrap.append(form);}
async function libraryPage(){prompts=(await api('prompts')).prompts;app.replaceChildren(node('h1','Thư viện lời nhắc'));app.append(node('p',me.role==='admin'?'Bạn quản lý thư viện chung và toàn bộ lời nhắc của thành viên.':'Bạn xem được thư viện chung và lời nhắc riêng của mình. Admin có quyền quản lý lời nhắc riêng.','muted'));const edit=node('div');edit.id='editor';app.append(edit);editor();const search=node('input');search.placeholder='Tìm lời nhắc…';search.setAttribute('aria-label','Tìm lời nhắc');app.append(search);const list=node('div');app.append(list);const draw=()=>{list.replaceChildren();for(const p of prompts.filter(p=>(p.title+' '+p.content).toLocaleLowerCase().includes(search.value.toLocaleLowerCase()))){const card=node('section',undefined,'card');card.append(node('h2',p.title),node('small',p.scope==='shared'?'Thư viện chung':(me.role==='admin'&&p.owner_phone?'Riêng tư · '+p.owner_phone:'Riêng tư')),node('p',p.content,'content'));action(card,'Sao chép',async()=>{await navigator.clipboard.writeText(p.content);message('Đã sao chép lời nhắc.');});if(me.role==='admin'||p.owner===me.id){action(card,'Sửa',()=>{editing=p;editor();document.getElementById('editor').scrollIntoView({behavior:'smooth'});},'secondary');action(card,'Xóa',async()=>{if(!confirm('Xóa lời nhắc này?'))return;await api('prompts',{id:p.id,action:'delete'});await libraryPage();},'danger');}list.append(card);}if(!list.childElementCount)list.append(node('p','Chưa có lời nhắc.','muted'));};search.oninput=draw;draw();}
let selectedAccountId=null;
const accountStatus={approved:'Đang hoạt động',pending:'Chờ duyệt',blocked:'Đã khóa'};
function summary(label,value){const card=node('div',undefined,'summary-card');card.append(node('small',label),node('strong',value));return card;}
function profileForm(account,managing=false){const form=document.createElement('form');form.className='profile-form';form.append(node('h2',managing?'Thông tin thành viên':'Thông tin của tôi'));const phone=field(form,'Số điện thoại đăng nhập','phone','tel');phone.value=account.phone;phone.readOnly=true;phone.required=false;form.append(node('small','Số điện thoại gắn với tài khoản đăng nhập.'));for(const [name,label,type] of [['display_name','Họ và tên','text'],['email','Email liên hệ','email'],['company','Đơn vị / doanh nghiệp','text']]){const input=field(form,label,name,type);input.required=false;input.value=account[name]||'';input.maxLength=name==='email'?254:name==='company'?160:100;}if(managing){const notes=field(form,'Ghi chú nội bộ — chỉ admin thấy','admin_notes','textarea');notes.required=false;notes.maxLength=2000;notes.value=account.admin_notes||'';}const save=node('button','Lưu thông tin');save.type='submit';form.append(save);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;message('');try{const data=Object.fromEntries(new FormData(form));delete data.phone;if(managing)data.id=account.id;await api(managing?'accounts':'account',data);await accountPage();message('Đã lưu thông tin tài khoản.');}catch(err){message(err.message);}finally{save.disabled=false;}};return form;}
async function accountPage(){const data=await api('account'),account=data.account;app.replaceChildren();const heading=node('div',undefined,'account-heading');heading.append(node('h1','Quản lý tài khoản'),node('p','Thông tin cá nhân và trạng thái sử dụng của bạn.','muted'));app.append(heading);const stats=node('div',undefined,'account-summary');stats.append(summary('Tài khoản',account.phone),summary('Vai trò',account.role==='admin'?'Quản trị viên':'Thành viên'),summary('Trạng thái',accountStatus[account.status]),summary('Ngày tham gia',new Date(account.created*1000).toLocaleDateString('vi-VN')));app.append(stats);const grid=node('div',undefined,'account-grid');grid.append(profileForm(account));const side=node('div');const plan=node('section',undefined,'card');plan.append(node('h2','Gói sử dụng'),node('p',account.plan_code==='none'?'Chưa gán gói sử dụng':account.plan_code),node('p','Hệ thống chưa triển khai đăng ký gói hoặc thu phí.','muted'));const payment=node('section',undefined,'card');payment.append(node('h2','Lịch sử thanh toán'),node('p','Chưa có giao dịch.','muted'));side.append(plan,payment);grid.append(side);app.append(grid);if(me.role==='admin')await accountDirectory();}
async function accountDirectory(){const accounts=(await api('accounts')).accounts;const section=node('section',undefined,'account-directory');section.append(node('h2','Quản lý thành viên'),node('p','Tìm tài khoản, cập nhật thông tin, duyệt hoặc khóa quyền sử dụng.','muted'));const filters=node('div',undefined,'row');const search=node('input');search.placeholder='Tìm số điện thoại, tên hoặc email…';search.setAttribute('aria-label','Tìm thành viên');const filter=node('select');filter.setAttribute('aria-label','Lọc trạng thái thành viên');for(const [value,label] of [['','Tất cả trạng thái'],['pending','Chờ duyệt'],['approved','Đang hoạt động'],['blocked','Đã khóa']]){const o=node('option',label);o.value=value;filter.append(o);}filters.append(search,filter);section.append(filters);const count=node('p',undefined,'muted'),list=node('div',undefined,'account-list'),detail=node('div');section.append(count,list,detail);app.append(section);const showDetail=account=>{selectedAccountId=account.id;detail.replaceChildren(profileForm(account,true));if(account.role!=='admin'){const actions=node('div',undefined,'member-actions');if(account.status!=='approved')action(actions,'Duyệt / Mở khóa',async()=>{await api('members',{id:account.id,status:'approved'});await accountPage();message('Đã duyệt tài khoản.');});if(account.status!=='blocked')action(actions,'Khóa tài khoản',async()=>{await api('members',{id:account.id,status:'blocked'});await accountPage();message('Đã khóa tài khoản.');},'danger');detail.append(actions);}else detail.append(node('p','Tài khoản quản trị không thể bị khóa tại đây.','muted'));};const draw=()=>{list.replaceChildren();const text=search.value.toLocaleLowerCase();const visible=accounts.filter(a=>(!filter.value||a.status===filter.value)&&[a.phone,a.display_name,a.email,a.company].join(' ').toLocaleLowerCase().includes(text));count.textContent=visible.length+' / '+accounts.length+' tài khoản';for(const a of visible){const row=node('div',undefined,'account-row');const identity=node('div');identity.append(node('strong',a.display_name||a.phone),node('p',a.display_name?a.phone:(a.email||'Chưa bổ sung thông tin'),'muted'));const badge=node('span',accountStatus[a.status],'status-badge status-'+a.status);row.append(identity,badge);action(row,'Chi tiết',()=>{showDetail(a);detail.scrollIntoView({behavior:'smooth',block:'start'});},'secondary');list.append(row);}if(!visible.length)list.append(node('p','Không có tài khoản phù hợp.','muted'));};search.oninput=filter.onchange=draw;draw();const selected=accounts.find(a=>a.id===selectedAccountId);if(selected)showDetail(selected);}

(async()=>{try{me=(await api('me')).user;if(me){document.getElementById('account').textContent=me.phone;document.getElementById('logout').classList.remove('hidden');document.getElementById('logout').onclick=async()=>{try{await api('logout',{});location.href='/login';}catch(e){message(e.message);}};if(me.role==='admin')document.getElementById('adminLink').classList.remove('hidden');}const path=location.pathname;document.querySelectorAll('header a').forEach(a=>{if(a.getAttribute('href')===path)a.setAttribute('aria-current','page');});if(path==='/login'||path==='/register'){if(me){location.replace('/');return;}authPage(path==='/register');}else if(!me)location.replace('/login');else if(path==='/account')await accountPage();else if(path==='/members'){if(me.role!=='admin'){message('Chỉ admin được quản lý thành viên.');return;}await membersPage();}else await libraryPage();}catch(e){message(e.message);}})();
</script></body></html>'''

WIDGET = """fetch('/member-api/me',{credentials:'same-origin'}).then(r=>r.json()).then(({user})=>{if(!user)location.href='/login';}).catch(()=>{});"""
